var status = new DownloadStatus();
List<Thread> threads = new ArrayList<>();
for (int i = 0; i < 10; i++) {
    var t = new Thread(() -> { for (int j = 0; j < 10_000; j++) status.incrementTotalBytes(); });
    t.start(); threads.add(t);
}
