public class DownloadStatus {
    private int totalBytes;
    private final Lock lock = new ReentrantLock();
    public void incrementTotalBytes() {
        lock.lock();
        try {
            totalBytes++;
        } finally {
            lock.unlock();
        }
    }
}

public class DownloadStatus {
    private int totalBytes;
    private final Object totalBytesLock = new Object();
    public void incrementTotalBytes() {
        synchronized (totalBytesLock) {
            totalBytes++;
        }
    }
}

